import{_ as e,o as a,c as n,ah as o}from"./chunks/framework.sPHStHqt.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/introduction.md","filePath":"getting-started/introduction.md","lastUpdated":1789630599000}'),r={name:"getting-started/introduction.md"};function s(i,t,h,l,u,d){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Krayin Multi-Tenant SaaS turns Krayin CRM into a product you can <em>sell</em>. Instead of running one CRM for your own business, you run a platform where many businesses each get their own CRM — on their own web address, with their own data — and you charge them a subscription for it.</p><div class="info custom-block"><p class="custom-block-title">Who this guide is for</p><p>This guide covers <strong>both</strong> sides of the platform:</p><ul><li><strong>Operators</strong> — you, running the platform: onboarding tenants, building plans, taking payment.</li><li><strong>Tenants</strong> — your customers, using the CRM they subscribed to.</li></ul><p>Each page says at the top which panel it&#39;s about, so you always know where you should be.</p></div><h2 id="the-two-audiences" tabindex="-1">The two audiences <a class="header-anchor" href="#the-two-audiences" aria-label="Permalink to &quot;The two audiences&quot;">​</a></h2><p>The platform has two completely separate front doors:</p><ul><li><strong>The super-admin panel</strong> — where <em>you</em> run the business. You sign in at <code>/super/login</code> and manage every tenant, plan, subscription and invoice from one place. This is the subject of the <strong>Super Admin</strong>, <strong>Subscriptions</strong> and <strong>Settings</strong> sections of this guide.</li><li><strong>A tenant&#39;s CRM</strong> — where <em>your customer</em> works. Each tenant gets a full Krayin CRM on their own subdomain, with its own admin login at <code>/admin/login</code>. The <strong>Tenants</strong> section covers this side.</li></ul><h2 id="what-a-tenant-gets" tabindex="-1">What a tenant gets <a class="header-anchor" href="#what-a-tenant-gets" aria-label="Permalink to &quot;What a tenant gets&quot;">​</a></h2><p>When a business signs up, they get a genuine, self-contained CRM — not a limited demo:</p><ul><li>Their own <strong>subdomain</strong>, e.g. <code>acme.yourplatform.com</code>, and optionally their own <a href="/tenants/custom-domains">custom domain</a>.</li><li>A private CRM with <strong>Leads</strong>, <strong>Quotes</strong>, <strong>Contacts</strong>, <strong>Organizations</strong> and pipelines.</li><li>Their own team of users, roles and settings — entirely separate from every other tenant.</li></ul><h2 id="what-you-get-as-the-operator" tabindex="-1">What you get as the operator <a class="header-anchor" href="#what-you-get-as-the-operator" aria-label="Permalink to &quot;What you get as the operator&quot;">​</a></h2><p>From the super-admin panel you can:</p><ul><li>See and manage every <a href="/super-admin/tenant-management">tenant</a> on the platform.</li><li>Watch activity across all tenants at a glance on the <a href="/super-admin/dashboard">dashboard</a>, and view cross-tenant <a href="/super-admin/leads">Leads</a> and <a href="/super-admin/quotes">Quotes</a>.</li><li>Build subscription <a href="/subscriptions/plan-management">plans</a> — monthly, yearly, with offers and resource limits — and offer a <a href="/subscriptions/trials">free trial</a>.</li><li>Take payment through <a href="/settings/configuration">Stripe</a> and track every <a href="/subscriptions/subscribers">subscriber</a> and <a href="/subscriptions/invoices">invoice</a>.</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>Understand how tenants stay separated → <a href="/getting-started/architecture">Architecture</a></li><li>Get the platform running → <a href="/getting-started/installation">Installation</a></li><li>Jump straight to the operator&#39;s home base → <a href="/super-admin/dashboard">The Dashboard</a></li></ul>',14)])])}const p=e(r,[["render",s]]);export{g as __pageData,p as default};
